# Eindtoets 2 Inkoop en recht: eigen vragen over alle weken (week 0, versie E2).
W = 0
I, R = "Inkoop", "Recht"
EIND_TITEL = "Gemeente Lindewaard en Sportcentrum De Wielewaal"
EIND_UITLEG = "Een tweede vaste toets met nieuwe vragen over alle weken. De casussen gaan over de afvalinzameling van een gemeente en de aankoop van fitnessapparatuur, met inkoop en recht door elkaar."

# ---------- Inkoop MC ----------
mc("ire2-i01", W, I, "Een leverancier van werkplekverlichting verkoopt een lamp voor € 50. Hij rekent een winstmarge van 20% van de verkoopprijs. Wat is zijn kostprijs per lamp?",
   ["€ 40,00", "€ 41,67", "€ 45,00", "€ 30,00"], 0,
   "De marge is 20% van de verkoopprijs, dus € 10. De kostprijs is dan 80% van € 50 = € 40. € 41,67 krijg je als je € 50 door 1,20 deelt; dat klopt alleen als de marge over de kostprijs gaat.")
mc("ire2-i02", W, I, "Een academisch ziekenhuis besteedt jaarlijks miljoenen aan het beheer van zijn ICT-werkplekken. Maar een paar aanbieders kunnen dat op deze schaal, en uitval legt de patiëntenzorg stil. Welke aanpak past volgens Kraljic?",
   ["Routineproduct: zo efficiënt mogelijk bestellen en bundelen",
    "Hefboomproduct: aanbieders scherp tegen elkaar uitspelen op prijs",
    "Knelpuntproduct: vooral een grote buffervoorraad aanleggen",
    "Strategisch product: een lange partnership, vaak single sourcing"], 3,
   "Hoog financieel belang en hoog leveringsrisico: strategisch. Daar past een langdurige relatie of partnership, vaak met bewust één leverancier (single sourcing).")
mc("ire2-i03", W, I, "Een Nederlandse verzekeraar laat de facilitaire meldingen van zijn medewerkers afhandelen door een servicedesk in Portugal, met één uur tijdsverschil. Welke vorm van uitbesteden is dit?",
   ["Nearshore en off-site", "Offshore en on-site", "Nearshore en on-site", "Offshore en turnkey"], 0,
   "Nearshore: uitbesteden binnen korte reisafstand of in dezelfde of een naburige tijdzone. Off-site: de taak wordt buiten het eigen terrein uitgevoerd. Offshore is uitbesteden aan een organisatie in een ander, vaak ver, land.")
mc("ire2-i04", W, I, "De directie van een zorginstelling wil de komende jaren vooral investeren in de beleving van bewoners. De inkoper stemt de inkoopplannen daarom af met de afdelingen en zoekt in de markt wat daarbij past. Welke rol van inkoop zie je hier?",
   ["De brugfunctie tussen interne gebruikers en de markt", "De make-or-buy-beslissing over zelf doen of uitbesteden", "Maverick buying buiten de contracten om", "Een should-cost-analyse van de kostprijs"], 0,
   "Inkoopbeleid is afgeleid van het organisatiebeleid en sluit aan op de wensen van interne gebruikers. Inkoop vertaalt die wensen naar de markt: de brugfunctie tussen gebruiker en markt.")
mc("ire2-i05", W, I, "Een hogeschool heeft als strategisch doel: 'studenten en medewerkers zijn tevreden over de catering'. Welke uitwerking hoort op operationeel niveau?",
   ["De tevredenheid over de catering is minimaal een 7,5",
    "95% van de klanten wacht maximaal 5 minuten aan de kassa",
    "Studenten en medewerkers zijn tevreden over het eten",
    "De cateraar werkt met een gecertificeerd kwaliteitssysteem"], 1,
   "Strategisch is het doel zelf, tactisch de tevredenheidsnorm van 7,5, en operationeel een concreet meetbare prestatie in het dagelijkse werk, zoals de wachttijd. Elk niveau draagt bij aan het niveau erboven. Een certificaat is geen KPI.")
mc("ire2-i06", W, I, "In de SLA met een facilitaire dienstverlener staat: 'Een melding geldt als opgelost zodra de melder dat in het FMIS heeft bevestigd.' Welk onderdeel van een SLA is dit volgens Van der Honing?",
   ["Een definitie van een begrip", "De overlegstructuur", "Een prestatie-indicator met score", "Een gunningscriterium"], 0,
   "De meeste SLA's bevatten definities van begrippen (zoals 'opgelost' of 'op tijd'), de overlegstructuur en de prestatie-indicatoren met de te behalen score. Deze zin legt vast wat 'opgelost' betekent.")
mc("ire2-i07", W, I, "Een schoonmaakbedrijf bepaalt zijn uurtarief door net onder de tarieven van de twee grootste concurrenten in de regio te gaan zitten. Welke methode van prijsstelling gebruikt het?",
   ["De kostprijsplusmethode", "Concurrentiegeoriënteerde prijsstelling", "Klantgeoriënteerde prijsstelling", "Dumping op de Nederlandse markt"], 1,
   "Bij concurrentiegeoriënteerde prijsstelling zijn de prijzen van concurrenten leidend. Bij kostprijsplus tel je een opslag op de eigen kostprijs, bij klantgeoriënteerd is de waardeperceptie van de klant leidend. Dumping is een lagere prijs in het buitenland dan thuis.")
mc("ire2-i08", W, I, "Een inkoper ontdekt dat de leverancier van het nieuwe toegangssysteem bezoekersgegevens onbeveiligd opslaat. Hij meldt dit intern en laat het in het contract regelen. Bij welk principe van de NEVI-gedragscode hoort dit vooral?",
   ["Maatschappelijke waarde", "Integriteit en objectiviteit", "Deskundigheid en verantwoording", "Transparantie (art. 1.9 Aw)"], 2,
   "Deskundigheid en verantwoording gaat steeds meer ook over cybersecurity in de keten en over zorgvuldig omgaan met data en algoritmen: risico's signaleren en melden hoort daarbij. Transparantie uit art. 1.9 Aw is een aanbestedingsbeginsel, geen NEVI-principe.")

# ---------- Recht MC ----------
mc("ire2-r01", W, R, "Een private sportvereniging laat een sportcomplex bouwen van € 6 miljoen. De gemeente betaalt daarvan € 4 miljoen subsidie. Moet de vereniging de bouw Europees aanbesteden?",
   ["Nee, een private vereniging is nooit een aanbestedende dienst",
    "Ja, als gesubsidieerde instelling: ruim 50% subsidie voor een werk boven de drempel",
    "Nee, want de subsidie zelf ligt onder de drempel voor werken",
    "Ja, maar alleen de inrichting, want leveringen vallen altijd onder art. 2.8"], 1,
   "Art. 2.8 Aw: meer dan 50% subsidie (hier twee derde) voor een werk, en € 6 miljoen ligt boven € 5.404.000. De subsidieverlener moet de naleving afdwingen. Leveringen vallen juist niet onder art. 2.8, tenzij ze ondergeschikt zijn aan het werk of de dienst.")
mc("ire2-r02", W, R, "Een waterschap besteedt de schoonmaak van zijn kantoren aan in drie percelen, één per regio: € 70.000, € 90.000 en € 100.000. Mag het het perceel van € 70.000 met een beroep op de percelenregeling zonder Europese procedure gunnen?",
   ["Ja, want het perceel ligt onder € 80.000",
    "Nee, € 70.000 is meer dan 20% van de totale waarde van € 260.000",
    "Ja, want elk perceel ligt afzonderlijk onder de drempel van € 216.000",
    "Nee, want de percelenregeling geldt alleen voor werken"], 1,
   "Bij leveringen en diensten moet het perceel ≤ € 80.000 zijn én mogen de percelen die je zo gunt samen maximaal 20% van de totale waarde zijn (art. 2.18 en 2.19 Aw). 20% van € 260.000 is € 52.000. Percelen tel je voor de raming bij elkaar op; los bekijken is splitsen.")
mc("ire2-r03", W, R, "Een gemeente laat een nieuw stadskantoor bouwen (€ 7 miljoen) en laat dezelfde aannemer daarna een jaar het technisch onderhoud doen (€ 150.000). Hoe kwalificeer je de opdracht?",
   ["Een werk, want de bouw is het hoofdvoorwerp; boven € 5.404.000",
    "Een dienst, want onderhoud is altijd een dienst; boven € 216.000",
    "Een concessie voor werken, want het gebouw wordt geëxploiteerd",
    "Een levering, want bij leveringen en diensten telt de hoogste waarde"], 0,
   "Bij werken met diensten bepaal je het hoofdvoorwerp: wat is essentieel en kenmerkend (Gestion Hotelera). Hier is dat de bouw; het onderhoud is bijkomstig. Er is geen exploitatierisico, dus geen concessie.")
mc("ire2-r04", W, R, "Een gemeente wil het groenonderhoud zonder aanbesteding gunnen aan Groen B.V. Zij bezit alle aandelen en houdt toezicht als op een eigen dienst. Groen B.V. doet 70% van haar werk voor de gemeente en 30% voor bedrijven. Mag dat?",
   ["Ja, want de gemeente bezit alle aandelen en houdt toezicht als op een eigen dienst",
    "Nee, want meer dan 80% van de werkzaamheden moet voor de gemeente zijn",
    "Ja, zolang de opdrachtwaarde onder de drempel voor werken van € 5.404.000 blijft",
    "Nee, want quasi-inbesteden is alleen toegestaan bij opdrachten voor werken"], 1,
   "Quasi-inbesteden (art. 2.24a Aw) vraagt drie cumulatieve voorwaarden: toezicht als op een eigen dienst, meer dan 80% van de werkzaamheden voor de dienst, en geen directe participatie van particulier kapitaal. Met 70% faalt de tweede voorwaarde.")
mc("ire2-r05", W, R, "In de algemene voorwaarden van een leverancier staat dat ziekte van zijn eigen personeel en vertraging bij zijn toeleveranciers als overmacht gelden. Wat doet de leverancier hiermee, en mag dat?",
   ["Hij verruimt zijn eigen overmacht; dat mag in beginsel, art. 6:75 BW is regelend",
    "Niets, want art. 6:75 BW is dwingend recht en het beding is dus nietig",
    "Hij beperkt de aansprakelijkheid van de wederpartij bij overmacht",
    "Hij legt een eigendomsvoorbehoud vast tot volledige betaling (art. 3:92 BW)"], 0,
   "Overmacht (art. 6:75 BW) is regelend recht. Gebruikers breiden in hun AV het eigen overmachtsbegrip uit en perken dat van de wederpartij in (zoals Heijmans art. 10). De wederpartij kan zo'n beding wel aantasten als het onredelijk bezwarend is (art. 6:233 sub a), als zij daar een beroep op kan doen.")
mc("ire2-r06", W, R, "Een afgewezen inschrijver wil dat de rechter een al gesloten overeenkomst tussen de gemeente en de winnaar vernietigt en daarnaast volledige schadevergoeding toekent. Welke procedure past daarbij?",
   ["Een kort geding", "Een bodemprocedure", "Een klacht bij de ACM", "Een bezwaarschrift bij de gemeente"], 1,
   "Vernietiging (art. 4.15 e.v. Aw) en schadevergoeding (art. 6:162 BW) zijn voorzieningen van de bodemprocedure. Een kort geding geeft alleen voorlopige voorzieningen, zoals een verbod tot gunning of een voorschot. De ACM kan een boete opleggen, maar vernietigt geen overeenkomst.")
mc("ire2-r07", W, R, "Een Nederlandse gemeente koopt meubilair bij een Belgisch bedrijf dat vanuit België levert. In de AV van de leverancier staat een onredelijk bezwarend beding. Geldt de Nederlandse AV-regeling (art. 6:231 e.v. BW) dwingend?",
   ["Ja, want de koper is gevestigd in Nederland en daar wordt het meubilair gebruikt",
    "Nee, bij twee zakelijke partijen van wie er één buiten Nederland zit, niet dwingend",
    "Ja, want voor een aanbestedende dienst geldt de regeling altijd dwingend",
    "Nee, want bij een internationale koop is de AV-regeling nooit van toepassing"], 1,
   "Art. 6:247 lid 2 BW: zijn beide partijen zakelijk en zit er één niet in Nederland, dan geldt de regeling niet dwingend. Lid 1 (twee Nederlandse zakelijke partijen) en lid 4 (Nederlandse consument) zijn wel dwingend. Het gaat om de vestiging van waaruit gepresteerd wordt.")
mc("ire2-r08", W, R, "Een leverancier levert op 1 maart koffiemachines aan een bedrijf; de betaling is op 1 april opeisbaar. Het bedrijf betaalt niet. Op 1 juni wil de leverancier de machines, die nog onaangeroerd in de doos staan, terughalen met het recht van reclame. Kan dat?",
   ["Ja, want de machines zijn nog in dezelfde staat",
    "Nee, de vervaltermijnen van 6 weken en 60 dagen zijn allebei verstreken",
    "Ja, want het recht van reclame verjaart pas na twee jaar",
    "Nee, want het recht van reclame bestaat alleen bij consumentenkoop"], 1,
   "Recht van reclame (art. 7:39 BW) heeft een korte vervaltermijn (art. 7:44 BW): 6 weken na opeisbaarheid is 13 mei, 60 dagen na aflevering is 30 april. Op 1 juni zijn beide verstreken. Dezelfde staat is wel een voorwaarde, maar niet genoeg. Verval kan, anders dan verjaring, niet worden gestuit.")

# ---------- open ----------
op("ire2-o1", W, I, "Een gemeente wil haar inkooppakket indelen met de matrix van Kraljic. Deel deze drie in en geef per product een passende sourcingkeuze met onderbouwing: (a) kantoorartikelen, (b) energie voor alle gemeentelijke gebouwen, (c) onderhoud van het besturingssysteem van de beweegbare stadsbrug, dat alleen de oorspronkelijke fabrikant kan leveren.",
   "(a) Routineproduct: laag financieel belang en laag leveringsrisico. Efficiënt inkopen: bundelen in één raamcontract of catalogus en er zo min mogelijk tijd aan besteden. (b) Hefboomproduct: hoog financieel belang, veel aanbieders en een laag leveringsrisico. Concurrentie benutten, bijvoorbeeld met multiple of dual sourcing en regelmatig opnieuw aanbesteden. (c) Hoog leveringsrisico, want er is maar één aanbieder: sole sourcing, je hebt geen keus. Is het financiële belang beperkt, dan is het een knelpuntproduct: leveringszekerheid borgen (een lang onderhoudscontract, reserveonderdelen, kennis vastleggen) en zoeken naar alternatieven. Wie het financiële belang hoog inschat, kan ook strategisch onderbouwen: dan een lange relatie met de fabrikant.",
   ["Kantoorartikelen: routine met passende aanpak", "Energie: hefboom met concurrentie benutten", "Brugsysteem: knelpunt (of onderbouwd strategisch) met sole sourcing en leveringszekerheid", "Steeds financieel belang én leveringsrisico genoemd"])
op("ire2-o2", W, I, "Formuleer voor het contract voor de receptiedienst van een gemeentehuis één kritieke succesfactor en twee KPI's, elk met een norm en een meetmethode. Noem daarnaast de drie onderdelen die volgens Van der Honing in de meeste SLA's staan, en leg uit bij welke NEVI-pijler je deze afspraken gebruikt.",
   "KSF, bijvoorbeeld: bezoekers worden snel en gastvrij ontvangen. KPI 1: wachttijd aan de balie; norm: 90% van de bezoekers binnen 2 minuten geholpen; meting: maandelijkse steekproef of het bezoekersregistratiesysteem. KPI 2: bezoekerstevredenheid; norm: gemiddeld minimaal een 8; meting: korte enquête via een QR-code, per kwartaal gerapporteerd. (Ook goed: telefoon binnen drie keer overgaan opgenomen, 95%, gemeten via de telefooncentrale.) SLA: definities van begrippen, de overlegstructuur, en de prestatie-indicatoren met de te behalen score. Pijler 3, prestatiemanagement: prestaties meten en sturen met KPI's en SLA's, periodiek evalueren en samen verbeteren. Een KPI zonder norm is geen afspraak.",
   ["Eén passende KSF", "Twee KPI's met norm én meetmethode", "Drie onderdelen van een SLA", "Pijler 3 prestatiemanagement met uitleg"])
op("ire2-o3", W, R, "Een provincie wil een compleet nieuw concept voor plaats- en tijdonafhankelijk werken voor haar 2.000 medewerkers. Welke combinatie van locaties, ICT, inrichting en financiering de beste is, weet zij nog niet; daarvoor heeft zij de kennis van de markt nodig. Welke procedure adviseer je? Noem het artikel, het minimumaantal gegadigden, de gunningsmethode en twee aandachtspunten tijdens de procedure.",
   "De concurrentiegerichte dialoog (art. 2.28 Aw): de opdracht is zeer complex en de provincie kan objectief niet bepalen welke middelen en oplossingen nodig zijn, technisch, juridisch en financieel. Samen met marktpartijen stelt zij het programma van eisen en de oplossing vast. Selectie zoals bij de niet-openbare procedure, met minimaal 3 gegadigden (art. 2.99 lid 3 Aw). Gunnen altijd op beste prijs-kwaliteitverhouding, niet op laagste prijs (art. 2.29 sub i Aw volgens het antwoordmodel). Aandachtspunten: geen cherry picking (oplossingen van de een niet doorspelen aan een ander), vertrouwelijk omgaan met informatie, een functionele vraag, de criteria al in de aankondiging, en over de definitieve inschrijving wordt niet onderhandeld. Alternatief met onderbouwing: de mededingingsprocedure met onderhandeling (art. 2.30 Aw), waarbij je eerst inschrijft en daarna onderhandelt.",
   ["Concurrentiegerichte dialoog met art. 2.28 en de reden", "Minimaal 3 (art. 2.99 lid 3)", "Beste prijs-kwaliteitverhouding", "Twee aandachtspunten zoals cherry picking en vertrouwelijkheid"])
op("ire2-o4", W, R, "Glazenwasserij Helder v.o.f. (12 medewerkers, geen openbare jaarrekening) koopt een hoogwerker bij een grote leverancier. Situatie 1: in de AV van de leverancier, waarnaar de offerte alleen verwijst ('gedeponeerd bij de KvK'), staat dat de leverancier nooit aansprakelijk is voor bedrijfsschade. Situatie 2: precies dezelfde exoneratieclausule staat in de koopovereenkomst zelf, die Helder heeft ondertekend. Beoordeel per situatie of en hoe Helder onder de clausule uit kan komen.",
   "Situatie 1: de clausule staat in algemene voorwaarden (art. 6:231 sub a BW); de leverancier is gebruiker, Helder wederpartij. Helder is gebonden (art. 6:232), maar valt niet onder art. 6:235 (minder dan 50 personen, geen openbare jaarrekening) en kan dus een beroep doen op art. 6:233. Sub b jo. art. 6:234: de AV zijn niet ter hand gesteld, terwijl dat gewoon kon; alleen verwijzen naar de KvK is dan onvoldoende, dus vernietigbaar. Daarnaast eventueel sub a (onredelijk bezwarend). De zwarte en grijze lijst gelden niet, want Helder is geen consument. Situatie 2: de clausule staat niet in de AV maar in de overeenkomst zelf, dus art. 6:233 e.v. helpen niet. Alleen de beperkende werking van de redelijkheid en billijkheid (art. 6:248 lid 2 BW) blijft over. De rechter weegt dan onder meer schuld of opzet, groot tegenover klein bedrijf, verzekerbaarheid en soort schade, en is terughoudend.",
   ["Sit. 1: geen art. 6:235-partij, dus 6:233 beschikbaar", "Sit. 1: sub b jo. 6:234, verwijzen naar KvK onvoldoende", "Sit. 2: AV-regeling niet van toepassing", "Sit. 2: alleen art. 6:248 lid 2 met gezichtspunten"])

# ---------- casus ----------
cs("ire2-c1", W, R, "Gemeente Lindewaard regelt haar afvalinzameling",
   "Gemeente Lindewaard (fictief) wil de inzameling en verwerking van het bedrijfsafval van al haar gebouwen (stadhuis, sporthallen, bibliotheek en gemeentewerf) opnieuw regelen. De geraamde waarde is € 140.000 per jaar; het nieuwe contract loopt 3 jaar met een optie op twee keer één jaar verlenging. De wethouder wil het werk het liefst direct gunnen aan Lindewaard Afval B.V. Daarvan bezit de gemeente 60% van de aandelen en een particulier afvalbedrijf 40%; de B.V. werkt voor 90% voor de gemeente. Het college heeft ook een ambitie: 'We willen samen met leveranciers nieuwe oplossingen vinden om afval te voorkomen, en wie met goede ideeën komt, krijgt meer werk.'",
   [("Is de opdracht Europees aanbestedingsplichtig? Gebruik de drie W's met artikelen.",
     "Wie: de gemeente is een territoriaal lichaam en dus aanbestedende dienst (art. 1.1 Aw). Wat: een schriftelijke overeenkomst onder bezwarende titel tussen een aanbestedende dienst en een ondernemer, voor een dienst (inzameling en verwerking van afval). Waarde: opties en verlengingen tellen mee (art. 2.15 lid 2 Aw): 5 × € 140.000 = € 700.000. Dat ligt boven de drempel van € 216.000 voor andere aanbestedende diensten. Conclusie: aanbestedingsplichtig, tenzij een uitzondering geldt.",
     ["Wie met art. 1.1 Aw", "Wat: dienst met de kenmerken van een overheidsopdracht", "Waarde € 700.000 inclusief opties, boven € 216.000"]),
    ("Mag de gemeente de opdracht zonder aanbesteding gunnen aan Lindewaard Afval B.V.? En wat als zij in plaats daarvan gaat samenwerken met de afvalafdeling van de buurgemeente?",
     "Quasi-inbesteden (art. 2.24a Aw) vraagt drie cumulatieve voorwaarden: toezicht als op een eigen dienst, meer dan 80% van de werkzaamheden voor de dienst (90%, dat klopt) en geen directe participatie van particulier kapitaal. Het particuliere afvalbedrijf heeft 40% van de aandelen, dus de derde voorwaarde faalt (en toezicht als op een eigen dienst is met 60% twijfelachtig). Direct gunnen mag dus niet. Samenwerken met de buurgemeente zonder aparte rechtspersoon kan als publiek-publieke samenwerking (art. 2.24c Aw), mits het gaat om openbare diensten die beide moeten leveren, de samenwerking alleen in het openbaar belang is en de buurgemeente maximaal 20% van die activiteiten op de open markt verricht (Stadtreinigung Hamburg). Dan hoeft er niet aanbesteed te worden.",
     ["Drie voorwaarden art. 2.24a genoemd", "Particulier kapitaal (40%) laat inbesteden falen", "Publiek-publieke samenwerking art. 2.24c met voorwaarden"]),
    ("De gemeente besteedt toch aan. In welke fase van het fasemodel duurzaam inkopen past de ambitie van het college? Geef twee concrete manieren om die ambitie in de aanbesteding en het contract te vertalen.",
     "Fase 5, drijfveer voor innovatie: duurzaamheid moet tot nieuwe oplossingen leiden, leveranciers worden uitgedaagd en wie goede ideeën heeft krijgt meer opdrachten. Vertaling, bijvoorbeeld: (1) gunnen op beste prijs-kwaliteitverhouding met een kwaliteitscriterium 'plan voor afvalpreventie en hergebruik', met de weging vooraf bekend (art. 2.115 lid 4 Aw); (2) een KPI in de SLA, zoals 'minimaal 75% van het afval gescheiden ingezameld, maandelijks gerapporteerd', met jaarlijkse verbeterdoelen; (3) een contract gericht op samenwerking en flexibiliteit, met ruimte voor innovaties en een verlengingsoptie bij goede prestaties (pijler 5); (4) een marktconsultatie vooraf. Eisen moeten wel proportioneel blijven.",
     ["Fase 5 met kenmerken uit de casus", "Twee concrete vertalingen in aanbesteding of contract", "Weging vooraf bekend of KPI met norm"]),
    ("Een afgewezen inschrijver vindt het criterium 'plan voor afvalpreventie' te vaag en start op dag 12 na de afwijzingsbrief een kort geding. De uitspraak volgt pas over vijf weken. Mag de gemeente na dag 20 het contract tekenen? En wat kan de voorzieningenrechter bevelen?",
     "Nee. De Alcatel-termijn van 20 dagen (art. 2.127 Aw) loopt door tot de uitspraak in kort geding, als de afgewezen partij binnen de termijn een kort geding is begonnen. In kort geding kan de rechter onder meer een verbod tot gunning, staking van de procedure, een herbeoordeling of een heraanbesteding bevelen. Inhoudelijk toetst de rechter de transparantie: criteria moeten duidelijk, precies en ondubbelzinnig zijn, zodat elke redelijk geïnformeerde en normaal zorgvuldige inschrijver ze hetzelfde begrijpt (art. 1.9 Aw).",
     ["Nee: standstill loopt door tot de uitspraak", "Twee voorzieningen in kort geding", "Transparantiemaatstaf met art. 1.9 Aw"])])
cs("ire2-c2", W, I, "Sportcentrum De Wielewaal koopt crosstrainers",
   "Sportcentrum De Wielewaal v.o.f. (fictief, 30 medewerkers, maakt geen jaarrekening openbaar) vervangt 20 crosstrainers. Offerte A komt van een Chinese fabrikant: € 2.600 per stuk, onderhoud € 350 per jaar, restwaarde na vijf jaar € 0. Offerte B komt van FitPro B.V. uit Ede (250 medewerkers): € 3.400 per stuk, onderhoud € 150 per jaar, restwaarde na vijf jaar € 400. De Wielewaal kiest FitPro. In de offerte van FitPro staat alleen: 'Op deze offerte zijn onze algemene voorwaarden van toepassing; deze zijn gedeponeerd bij de Kamer van Koophandel.' Daarin staat: 'Garantie 6 maanden. Na afloop van de garantietermijn vervalt elke aanspraak op herstel of vervanging.' De verkoper van FitPro zei bij de demonstratie dat de toestellen 'minstens tien jaar meegaan'. Na negen maanden vallen zes crosstrainers uit door een kapotte aandrijving.",
   [("Bereken de TCO per crosstrainer over vijf jaar voor A en B. Welke offerte is goedkoper, en welke verborgen kosten van offerte A zitten nog niet in je berekening?",
     "A: € 2.600 + 5 × € 350 − € 0 = € 4.350. B: € 3.400 + 5 × € 150 − € 400 = € 3.750. B is € 600 per stuk goedkoper, voor 20 toestellen € 12.000, ondanks de hogere aanschafprijs. Verborgen kosten bij A: transport, invoerrechten en douane, wisselkoersrisico, een langere levertijd, kwaliteitsrisico en extra controle, lastiger communicatie en service op afstand (wie repareert er?), en mogelijk een kortere levensduur.",
     ["TCO A € 4.350 en B € 3.750 juist berekend", "Conclusie B goedkoper (ook totaal)", "Minstens drie verborgen kosten"]),
    ("Waar plaats je crosstrainers voor een sportcentrum in de matrix van Kraljic, en wat betekent dat voor de sourcingkeuze (aantal leveranciers, lokaal of global)?",
     "Voor een sportcentrum is de apparatuur een groot deel van de uitgaven (hoog financieel belang), en er zijn veel aanbieders (laag leveringsrisico): een hefboomproduct. Dan benut je de concurrentie, bijvoorbeeld met multiple of dual sourcing en scherp onderhandelen. Wie het leveringsrisico hoger inschat (uitval van toestellen kost direct omzet), kan strategisch onderbouwen, met een langere relatie met één leverancier. Lokaal (FitPro): korte levertijd, service dichtbij, minder gedoe met douane en cultuurverschillen. Global: lagere kostprijs, maar verborgen kosten en meer risico. Gezien de TCO en de service ligt lokaal hier voor de hand.",
     ["Hefboom (of onderbouwd strategisch) met financieel belang en risico", "Passend aantal leveranciers", "Lokaal tegenover global met voor- en nadelen"]),
    ("Kan De Wielewaal de garantiebepaling in de AV van FitPro aantasten? Noem de artikelen.",
     "De bepaling staat in algemene voorwaarden (art. 6:231 sub a BW): FitPro is gebruiker (sub b), De Wielewaal wederpartij (sub c). De Wielewaal is gebonden, ook zonder de AV te kennen (art. 6:232). Maar De Wielewaal valt niet onder art. 6:235 (minder dan 50 personen, geen openbare jaarrekening), dus kan zij een beroep doen op art. 6:233. Sub b jo. art. 6:234: FitPro heeft de AV niet ter hand gesteld, terwijl dat redelijkerwijs kon (gewoon meesturen); alleen verwijzen naar de KvK is dan onvoldoende. De bepaling is dus vernietigbaar. De zwarte en grijze lijst gelden niet, want De Wielewaal is geen consument.",
     ["Gebruiker en wederpartij met art. 6:231", "Geen art. 6:235-partij", "Vernietigbaar via 6:233 sub b jo. 6:234"]),
    ("Stel dat de garantiebepaling is vernietigd. Welke rechten heeft De Wielewaal bij de zes kapotte crosstrainers, en waar moet het sportcentrum op letten? Wat was de uitkomst geweest als de bepaling wél gold?",
     "Zonder de bepaling geldt de wet. De verkoper zei dat de toestellen minstens tien jaar meegaan; na negen maanden kapot voldoet niet aan de redelijke verwachtingen, gelet op de mededelingen van de verkoper: non-conform (art. 7:17 BW). Recht op herstel of vervanging op kosten van de verkoper (art. 7:21 BW), en daarnaast de rechten uit Boek 6, zoals gedeeltelijke ontbinding en schadevergoeding. Let op de klachtplicht: binnen bekwame tijd na ontdekking klagen (art. 7:23 BW); de twee maanden is een regel voor consumenten. Gold de bepaling wel, dan was het een negatieve garantie, en die mag bij een zakelijke koop (regelend recht): dan had De Wielewaal na de zes maanden geen recht meer op herstel of vervanging.",
     ["Non-conformiteit art. 7:17 met de mededeling van de verkoper", "Rechten art. 7:21 en Boek 6", "Klachtplicht art. 7:23", "Negatieve garantie mag bij zakelijke koop"])])
